        const spelled = text(token(guard));
        const negated = spelled.startsWith("¬");
        /** @type {import("./types.js").Guard} */
        const read = { feature: spelled.slice(negated ? 1 : 0, -1), kind: spelled.endsWith("!") ? "warning" : "gate", negated };
